{
    if (p != NULL) {
        gm_instance_set_depth(p, v);
    }
}

static inline double gml_iget_persistent(gm_instance_t *p)
{
    if (p == NULL) {
        return 0.0;
    }
    return p->persistent ? 1.0 : 0.0;
}

static inline void gml_iset_persistent(gm_instance_t *p, double v)
{
    if (p != NULL) {
        p->persistent = v > 0.5;
    }
}

